from itertools import permutations

cats = {
 'opinion': "silly terrible wonderful lovely repulsive nice awful good ridiculous mysterious",
 'size': "medium-size massive huge large tiny big little small enormous midsize normal-size",
 'age': "new archaic old-fashioned ancient brand-new old",
 'shape': "prismlike rectangular square pyramidal circular triangular spherical",
 'color': "yellow violet aqua crimson maroon magenta cyan blue pink brown indigo red gray green white black",
 'origin': "egyptian chinese turkish vietnamese german bangladeshi mexican iranian russian ethiopian filipino indonesian thai",
 'material': "plastic wood wool iron fiberglass cardboard glass leather cloth paper",
 'purpose': "typing whittling walking smoking hiking drinking snorkeling exercise eating driving",
}
w2c = {}
for c, ws in cats.items():
    for w in ws.split():
        w2c[w] = c

examples = """yellow ruler|silly violet fork|silly aqua key|prismlike sunglasses|new ruler|archaic apple|terrible stapler|crimson dog|medium-size spoon|old-fashioned hammer|prismlike pen|typing ruler|new guitar|plastic egyptian necklace|wonderful shoe|whittling ruler|lovely piano|new scissors|whittling saw|lovely aqua necklace|massive spoon|ancient exercise candle|silly brown jar|rectangular stapler|prismlike bird|walking car|wood chinese hat|smoking apple|little square plate|old-fashioned typing flower pot|repulsive canvas|hiking hat|wool speaker|turkish old green box|huge dog|pyramidal lamp|prismlike saw|circular flower pot|maroon chair|egyptian jar|magenta bird|hiking spoon|iron sofa|large hat|tiny speaker|fiberglass vietnamese bottle|cyan hat|old-fashioned car key|new smoking toolbox|big triangular earring|terrible hat|maroon piano|ridiculous indigo sunglasses|archaic snorkeling bicycle|cardboard sofa|lovely fork|circular bowl|pink guitar|medium-size car|large fork|blue candle|triangular plate|rectangular spoon|huge scissors|massive knife|small circular pencil|small spherical key|ancient drinking candle|new drill|new drinking bowl|triangular sunglasses|brand-new cup|mysterious hammer|enormous triangular calculator|whittling stapler|square bed|cardboard typing lovely flower pot|german piano|glass bangladeshi watch|wool hammer|triangular house|iron mexican vase|massive rectangular screwdriver|prismlike necklace|nice red flower pot|old-fashioned pen|awful magenta spoon|russian bird|crimson flower pot|tiny pyramidal vase|good key|leather iranian box|repulsive gray ring|ethiopian knife|brown bag|midsize circular chair|snorkeling trash can|new whittling fire extinguisher""".split('|')

options = {
 'A': "circular large old-fashioned driving good black sofa",
 'B': "wood filipino ancient smoking awful violet tiny prismlike fork",
 'C': "prismlike brand-new smoking ridiculous violet iranian paper bed",
 'D': "old drinking terrible white normal-size square wrench",
 'E': "cloth thai brand-new eating good blue plate",
 'F': "fiberglass indonesian brand-new smoking wonderful cyan massive bottle",
 'G': "big rectangular archaic smoking terrible yellow vase",
 'H': "thai old drinking nice green massive pyramidal clock",
 'I': "glass bangladeshi old-fashioned snorkeling nice magenta prismlike canvas",
 'J': "spherical little ancient walking good indigo bangladeshi jar",
}

def adj_cats(s):
    out = []
    for t in s.split():
        if t in w2c:
            out.append(w2c[t])
        else:
            break
    return out

# sanity: every example must parse with at least all-but-noun tokens classified
cons = set()
for s in examples:
    toks = s.split()
    cs = adj_cats(s)
    for i in range(len(cs)):
        for j in range(i + 1, len(cs)):
            if cs[i] == cs[j]:
                print("same category twice in", s)
            cons.add((cs[i], cs[j]))
print("constraints:", sorted(cons))

catlist = list(cats.keys())
valid = []
for p in permutations(catlist):
    pos = {c: i for i, c in enumerate(p)}
    if all(pos[a] < pos[b] for a, b in cons):
        valid.append(pos)
print("consistent total orders:", len(valid))

results = {}
for pos in valid:
    good = ""
    for L, s in options.items():
        toks = s.split()
        cs = adj_cats(s)
        assert len(cs) == len(toks) - 1, s
        idx = [pos[c] for c in cs]
        if all(idx[i] < idx[i + 1] for i in range(len(idx) - 1)):
            good += L
    results[good] = results.get(good, 0) + 1
print("outcomes (correct set -> number of consistent orders):", results)

# per-option determination
for L, s in options.items():
    cs = adj_cats(s)
    vals = set()
    for pos in valid:
        idx = [pos[c] for c in cs]
        vals.add(all(idx[i] < idx[i + 1] for i in range(len(idx) - 1)))
    print(L, cs, vals)

submitted = "K"
if len(valid) == 0:
    print("UNSUPPORTED")
elif len(results) == 1:
    ans = list(results.keys())[0] or "K"
    print("expected:", ans, "submitted:", submitted)
    print("CHECK PASS" if ans == submitted else "CHECK FAIL")
else:
    if "" not in results or len(results) > 1 and "" in results and results[""] != len(valid):
        if "" not in results:
            print("submitted K is wrong under every consistent order")
            print("CHECK FAIL")
        else:
            print("order underdetermined; outcomes differ")
            print("CHECK UNKNOWN")
