import json, re, math
from itertools import combinations

path = """M 24.38698,-19.9365 L 29.3405,-17.62663 M 0.0,7.0 L 0.0,5.46 M 10.35209,0.0 L 10.35209,-7.0986 M 20.49493,-28.84999 L 17.75636,-22.97711 M 20.49493,-21.75139 L 24.38698,-19.9365 M 18.29129,-17.02568 L 20.49493,-21.75139 M 17.75636,-22.97711 L 15.16487,-17.41963 M 10.35209,-7.0986 L 0.0,-7.0986 M 22.10067,8.68911 L 19.34832,10.61633 M 2.5205,-5.64339 L 6.14757,-3.5493 M 10.35209,-4.68508 L 10.35209,0.0 M 10.35209,-7.0986 L 10.35209,-4.68508 M 20.49493,-25.44266 L 20.49493,-28.84999 M 0.0,-7.0986 L 2.5205,-5.64339 M 6.14757,-3.5493 L 2.33608,-1.34873 M 24.85302,6.76189 L 22.10067,8.68911 M 15.93065,-11.96326 L 17.25429,-14.80182 M 20.49493,-21.75139 L 20.49493,-25.44266 M 19.34832,10.61633 L 17.21983,12.10671 L 11.74658,15.93912 M 10.35209,1.96 L 10.35209,3.3712 M 0.0,5.46 L 0.0,0.0 M 4.03732,0.0 L 10.35209,0.0 M 10.35209,7.0 L 7.55703,7.0 M 10.35209,0.0 L 15.93065,-11.96326 M 10.35209,3.3712 L 10.35209,7.0 M 2.33608,-1.34873 L 0.0,0.0 M 34.99586,-14.98949 L 24.85302,6.76189 M 15.16487,-17.41963 L 10.35209,-7.0986 M 11.74658,15.93912 L 11.17484,9.40408 M 0.0,0.0 L 4.03732,0.0 M 11.17484,9.40408 L 10.79637,5.0782 M 29.3405,-17.62663 L 34.99586,-14.98949 M 10.35209,0.0 L 10.35209,1.96 M 10.79637,5.0782 L 10.35209,0.0 M 7.55703,7.0 L 0.0,7.0 M 17.25429,-14.80182 L 18.29129,-17.02568"""

# parse
segs = []
for sub in re.split(r'(?=M)', path):
    sub = sub.strip()
    if not sub:
        continue
    pts = [tuple(map(float, m)) for m in re.findall(r'(-?\d+\.?\d*),(-?\d+\.?\d*)', sub)]
    for i in range(len(pts) - 1):
        segs.append((pts[i], pts[i + 1]))

def key(p):
    return (round(p[0], 3), round(p[1], 3))

allpts = {}
for a, b in segs:
    for p in (a, b):
        allpts.setdefault(key(p), p)
P = list(allpts.values())

def dist_pt_seg(p, a, b):
    dx, dy = b[0]-a[0], b[1]-a[1]
    L2 = dx*dx + dy*dy
    if L2 == 0:
        return math.hypot(p[0]-a[0], p[1]-a[1]), 0
    t = ((p[0]-a[0])*dx + (p[1]-a[1])*dy) / L2
    tc = max(0, min(1, t))
    return math.hypot(p[0]-(a[0]+tc*dx), p[1]-(a[1]+tc*dy)), t

# split at T-junctions
edges = set()
for a, b in segs:
    on = [a, b]
    for p in P:
        d, t = dist_pt_seg(p, a, b)
        if d < 1e-3 and 1e-6 < t < 1 - 1e-6:
            on.append(p)
    dx, dy = b[0]-a[0], b[1]-a[1]
    on.sort(key=lambda p: (p[0]-a[0])*dx + (p[1]-a[1])*dy)
    for i in range(len(on) - 1):
        k1, k2 = key(on[i]), key(on[i+1])
        if k1 != k2:
            edges.add(tuple(sorted((k1, k2))))

nodes = sorted({k for e in edges for k in e})
idx = {k: i for i, k in enumerate(nodes)}
adj = [[] for _ in nodes]
for a, b in edges:
    adj[idx[a]].append(idx[b])
    adj[idx[b]].append(idx[a])

def inside_strict(pt, poly):
    n = len(poly)
    for i in range(n):
        d, _ = dist_pt_seg(pt, poly[i], poly[(i+1) % n])
        if d < 1e-3:
            return False
    c = False
    x, y = pt
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i+1) % n]
        if (y1 > y) != (y2 > y):
            xi = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
            if xi > x:
                c = not c
    return c

def cross(u, v):
    return u[0]*v[1] - u[1]*v[0]

def dot(u, v):
    return u[0]*v[0] + u[1]*v[1]

def simplify(poly):
    poly = list(poly)
    changed = True
    while changed and len(poly) > 3:
        changed = False
        n = len(poly)
        for i in range(n):
            a, b, c = poly[i-1], poly[i], poly[(i+1) % n]
            u = (b[0]-a[0], b[1]-a[1])
            v = (c[0]-b[0], c[1]-b[1])
            lu, lv = math.hypot(*u), math.hypot(*v)
            if lu < 1e-9 or lv < 1e-9 or abs(cross(u, v)) < 1e-3 * lu * lv:
                poly.pop(i)
                changed = True
                break
    return poly

def classify(poly):
    n = len(poly)
    E = [(poly[(i+1) % n][0]-poly[i][0], poly[(i+1) % n][1]-poly[i][1]) for i in range(n)]
    L = [math.hypot(*e) for e in E]
    cr = [cross(E[i], E[(i+1) % n]) for i in range(n)]
    convex = all(c > 0 for c in cr) or all(c < 0 for c in cr)
    def par(u, v):
        return abs(cross(u, v)) < 1e-2 * math.hypot(*u) * math.hypot(*v)
    def perp(u, v):
        return abs(dot(u, v)) < 1e-2 * math.hypot(*u) * math.hypot(*v)
    def eq(x, y):
        return abs(x - y) < 1e-2 * max(x, y)
    if n == 3:
        right = any(perp(E[i], E[(i+1) % 3]) for i in range(3))
        return 4 if right else 3
    if n == 4:
        if not convex:
            return None
        p1, p2 = par(E[0], E[2]), par(E[1], E[3])
        if p1 and p2:
            if all(perp(E[i], E[(i+1) % 4]) for i in range(4)):
                return 2 if eq(L[0], L[1]) else 1
            return 5
        if p1 or p2:
            return 6
        return None
    if n == 5:
        if not convex:
            return 8
        reg = all(eq(L[0], l) for l in L)
        if reg:
            ang = [math.atan2(abs(cr[i]), -dot(E[i], E[(i+1) % 5])) for i in range(5)]
            reg = all(abs(ang[0]-a) < 1e-2 for a in ang)
        return 9 if reg else 7
    if n == 6:
        if convex and all(eq(L[0], l) for l in L):
            ang = [math.atan2(abs(cr[i]), -dot(E[i], E[(i+1) % 6])) for i in range(6)]
            if all(abs(ang[0]-a) < 1e-2 for a in ang):
                return 10
    return None

found = set()
