"M -15.59808,14.80251 L -15.59808,13.48251 L -15.59808,8.80251 M 0.0,14.80251 L 9.07607,14.80251")

# parse into segments
toks = path.replace(",", " ").split()
segs = []
cur = None
i = 0
while i < len(toks):
    t = toks[i]
    if t in ("M", "L"):
        p = (float(toks[i+1]) + 0.0, float(toks[i+2]) + 0.0)
        if t == "L" and cur is not None:
            segs.append((cur, p))
        cur = p
        i += 3
    else:
        i += 1

TOL = 1e-3
def key(p):
    return (round(p[0], 3) + 0.0, round(p[1], 3) + 0.0)

nodes = {}
for a, b in segs:
    for p in (a, b):
        nodes.setdefault(key(p), p)
pts = list(nodes.values())

def on_seg(p, a, b):
    ax, ay = a; bx, by = b; px, py = p
    cr = (bx-ax)*(py-ay) - (by-ay)*(px-ax)
    L = math.hypot(bx-ax, by-ay)
    if L == 0 or abs(cr)/L > TOL:
        return False
    d = ((px-ax)*(bx-ax) + (py-ay)*(by-ay))/L
    return -TOL <= d <= L + TOL

idx = {key(p): n for n, p in enumerate(pts)}
