    on.sort(key=lambda p: (p[0]-a[0])**2 + (p[1]-a[1])**2)
    for u, v in zip(on, on[1:]):
        iu, iv = idx[key(u)], idx[key(v)]
        if iu != iv:
            edges.add(frozenset((iu, iv)))

adj = {n: set() for n in range(len(pts))}
