def sub(a, b): return (a[0]-b[0], a[1]-b[1])
def cross(a, b): return a[0]*b[1] - a[1]*b[0]
def dot(a, b): return a[0]*b[0] + a[1]*b[1]
def norm(a): return math.hypot(a[0], a[1])

def reduce_poly(poly):
    changed = True
    while changed and len(poly) > 3:
        changed = False
        n = len(poly)
        for k in range(n):
            a, b, c = poly[k-1], poly[k], poly[(k+1) % n]
            u, v = sub(b, a), sub(c, b)
            if abs(cross(u, v)) / (norm(u)*norm(v)) < TOL:
                poly.pop(k)
                changed = True
                break
    return poly

def area(poly):
    return 0.5*sum(cross(poly[k], poly[(k+1) % len(poly)]) for k in range(len(poly)))

def classify(poly):
    n = len(poly)
    sides = [sub(poly[(k+1) % n], poly[k]) for k in range(n)]
    lens = [norm(s) for s in sides]
    def par(a, b): return abs(cross(a, b))/(norm(a)*norm(b)) < TOL
    def perp(a, b): return abs(dot(a, b))/(norm(a)*norm(b)) < TOL
    def eq(a, b): return abs(a-b) <= TOL*max(a, b) + 1e-3
    crs = [cross(sides[k], sides[(k+1) % n]) for k in range(n)]
    convex = all(c > 0 for c in crs) or all(c < 0 for c in crs)
    right_angles = [perp(sides[k], sides[(k+1) % n]) for k in range(n)]
    if n == 3:
        return 4 if any(right_angles) else 3
    if n == 4:
        if not convex:
            return None
        p1 = par(sides[0], sides[2]); p2 = par(sides[1], sides[3])
        if p1 and p2:
            if all(right_angles):
                return 2 if eq(lens[0], lens[1]) else 1
            return 5 if (not all(eq(lens[0], lens[1]) for _ in [0]) or True) else None
        if p1 != p2:
            return 6
        return None
    if n == 5 or n == 6:
        if not convex:
            return 8 if n == 5 else None
        reg = all(eq(lens[0], l) for l in lens)
        if reg:
            turn = [math.atan2(abs(crs[k]), dot(sides[k], sides[(k+1) % n])) for k in range(n)]
            reg = all(abs(turn[0]-t) < 1e-2 for t in turn)
        if n == 5:
            return 9 if reg else 7
        return 10 if reg else None
    return None

found = set()
detail = []
for cyc in cycle_list:
    poly = [pts[k] for k in cyc]
    poly = reduce_poly(poly)
    if abs(area(poly)) < 1e-3:
