    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}

sols = []
for p in permutations(names):
    pos = {n: i for i, n in enumerate(p)}

    def nbrs(n):
        i = pos[n]
        return [p[j] for j in (i - 1, i + 1) if 0 <= j < 4]

