        continue
    if any(comm("France", x) for x in nbrs("France")):
        continue
    if sum(comm("Britain", x) for x in nbrs("Britain")) != 1:
        continue
    sols.append(p)

matches = [k for k, v in options.items() if tuple(v) in [tuple(s) for s in sols]]

